package org.icu.sepsis.notes;
public final class ClinicalNoteStatus {private ClinicalNoteStatus(){}public static String label(String code){if(code==null)return "病程同步状态未取得";switch(code){case "disabled":return "病程来源同步未开启";case "not_configured":case "interface_config_missing":return "病程接口配置不完整";case "key_unavailable":return "病程快照密钥不可用";case "interface_http_error":return "病程接口返回非成功状态，请核对认证和路径";case "interface_content_type":return "病程接口响应类型不是约定的 JSON";case "interface_response_invalid":return "病程响应 JSON 语法或转义不合法，本批未保存";case "interface_response_schema_invalid":return "病程 JSON 已解析，但响应字段结构不符合约定";case "interface_binding_mismatch":case "binding_unconfirmed":return "病程患者或本次住院归属核验未通过";case "interface_business_error":return "病程接口业务返回码不是成功";case "interface_document_invalid":return "病程正文缺失或超过上限";case "interface_response_too_large":return "病程响应或文书数量超过读取上限";case "timeout":return "病程来源读取超时";case "interface_network_error":case "read_failed":return "病程来源读取失败";case "no_records":return "本次接口没有返回文书";case "synced":return "病程已同步";case "partial":return "病程仅部分读取或保存";case "completeness_unknown":return "已保存病程，来源完整性未确认";default:return "病程同步状态待核对";}}}
